@LOADER_REGISTRY.register(".tiff", ".tif")
def _load_tiff(path, ind_dict=None, channels="CZYX", **kwargs):
    """
    Load a TIFF image using AICSImage.

    Returns:
        ScalarImage containing the image tensor.
    """

    path_str = str(path)
    if ind_dict == None:
        path_str, ind_dict = split_path(path_str)
    
    # ome.tiff require a separate loader than regular tiff
    if is_ome_tiff(Path(path_str)):
       image_loader = OmeTiffReader
    else:
        image_loader = TiffReader

    reader = bioio_loader(ind_dict, loader=image_loader, channels=channels)

    return ScalarImage(path_str, reader=reader)

# %% ../nbs/002_io.ipynb #42c796c8
def _get_loader(path: Path):
    """
    Select appropriate loader based on file format.

    Priority:
        1. registry-based loader (exact match)
        2. format-based fallback (via extract_formats)
        3. default loader
    """

    # 1. Registry-based detection (fast path)
    loader = LOADER_REGISTRY.get(path)
    if loader:
        return loader

    # 2. Format-based detection (HDF5-aware)
    fmt = extract_formats(path)[0]

    if fmt == "HDF5":
        return _load_hdf5

    # 3. Default fallback
    return _load_default

# %% ../nbs/002_io.ipynb #d9629282
def _load_and_preprocess(
    file_path: PathLike,
    transforms: Callable|Iterable[Callable]|None =None,
    loader: Callable|None =None,
    channels: str ="CZYX",
    ind_dict: dict|None =None,
    npz_key: str|None =None,
) -> tuple[ScalarImage, PreprocessMetadata]:
    """
    Load image and apply preprocessing transforms.

    Also attaches file format metadata.
    """
    path = Path(file_path)

    image_loader = _get_loader(path)
    img = image_loader(path, loader=loader, channels=channels, ind_dict=ind_dict, npz_key=npz_key)

    img, meta = _preprocess(img, transforms)

    # format extraction
    meta.format = extract_formats(path)[0]
    # save channels info
    meta.layout = channels

    return img, meta

# %% ../nbs/002_io.ipynb #08b998f4
def _multi_sequence_stream(
    image_paths: Sequence[PathLike],
    transforms=None,
    loader=None,
    channels="CZYX",
    ind_dict=None,
    npz_key=None,
) -> Iterable[tuple[ScalarImage, PreprocessMetadata]]:
    """
    Lazily yield preprocessed image samples.

    Args:
        image_paths: Iterable of file paths.
        transforms: Optional transforms.
        reader: Optional reader.
        npz_key: Optional NPZ key.

    Yields:
        tuple (image, metadata)
    """
    for p in image_paths:
        yield _load_and_preprocess(
            p,
            transforms=transforms,
            loader=loader,
            channels=channels,
            ind_dict=ind_dict,
            npz_key=npz_key,
        )

# %% ../nbs/002_io.ipynb #f4177cc4
def image_reader(
    file_path: PathLike | Sequence[PathLike],
    lazy: bool = False,
    output: str = "tensor",
    transforms: Callable|list[Callable]|None = None,
    loader: Callable|None = None,
    channels: str ="CZYX",
    ind_dict: dict|None = None,
    npz_key: str|None = None,
    dtype=torch.float32,
    squeeze: bool = False,
    stack_axis: str = "C",
) -> (
    ScalarImage
    | list[ScalarImage]
    | tuple[ScalarImage, dict]
    | tuple[list[ScalarImage], dict]
    | np.ndarray
    | tuple[np.ndarray, dict]
    | torch.Tensor
    | tuple[torch.Tensor, dict]
    | tuple[torch.Tensor, dict]
    | MetaTensor
):
    """
    Main entry point for medical image loading.

    ----------------------------------------------------------------------
    OVERVIEW
    ----------------------------------------------------------------------
    Supports:
        - single image loading
        - multi-image / multi-sequence loading
        - lazy or eager execution
        - scalar, NumPy, tensor, and MetaTensor outputs
        - flexible axis control for multi-image stacking

    ----------------------------------------------------------------------
    AXIS MODEL
    ----------------------------------------------------------------------
    Two concepts define tensor layout:

    1. channels:
        Defines per-image axis layout (e.g. "CZYX")

    2. stack_axis:
        Defines how multi-image inputs are injected.

    RULES:

    CASE 1:
        If stack_axis is IN channels:
            → images are stacked along that axis (no new axis created)
            → that axis becomes sequence dimension

    CASE 2:
        If stack_axis is NOT in channels:
            → a new axis is created at stack_axis position
            → sequence dimension is inserted

    ----------------------------------------------------------------------
    OUTPUT MODES
    ----------------------------------------------------------------------
        "scalar"        -> ScalarImage or list[ScalarImage]
        "scalar+meta"   -> (ScalarImage, Meta) or (list, list)
        "nparray"       -> np.ndarray
        "nparray+meta"  -> (np.ndarray, Meta or list[Meta])
        "tensor"        -> torch.Tensor
        "tensor+meta"   -> (torch.Tensor, Meta or list[Meta])
        "metatensor"    -> MetaTensor

    ----------------------------------------------------------------------
    """

    # loader
    def _load(p):
        return _load_and_preprocess(
            p,
            transforms=transforms,
            loader=loader,
            channels=channels,
            ind_dict=ind_dict,
            npz_key=npz_key,
        )

    def _iter_multi():
        if lazy:
            return _multi_sequence_stream(
                file_path,
                transforms=transforms,
                loader=loader,
                channels=channels,
                ind_dict=ind_dict,
                npz_key=npz_key,
            )
        return (_load(p) for p in file_path)

    # tensor builder
    def _stack(imgs):

        tensors = []
        for img in imgs:
            t = img.data

            if squeeze:
                t = t.squeeze()

            t = t.to(dtype)

            tensors.append(t)

        # stack along a new dimension 
        t = torch.stack(tensors, dim=0)

        # CASE A: stack_axis NOT in channel_order → just insert new axis
        if stack_axis not in channels:
            # insert S as new semantic axis
            # (no fusion, no concat)

            return t
        
        # stack_axis EXISTS in channel_order → concatenate into that axis
        axis_idx = channels.index(stack_axis)

        # -------------------------------------------------
        # move stack dim (0) next to target axis
        # -------------------------------------------------
        perm = list(range(t.ndim))

        perm.remove(0)
        perm.insert(axis_idx + 1, 0)

        t = t.permute(*perm)

        # -------------------------------------------------
        # concatenate along stack_axis
        # -------------------------------------------------
        t = torch.cat(
            torch.unbind(t, dim=axis_idx + 1),
            dim=axis_idx
        )

        return t

    def _to_numpy(tensor):
        return tensor.detach().cpu().numpy()

    # -------------------------------------------------
    # detect multi
    # -------------------------------------------------
    is_multi = isinstance(file_path, Sequence) and not isinstance(file_path, (str, Path))

    # =====================================================
    # MULTI CASE
    # =====================================================
    if is_multi:
        imgs, metas = zip(*_iter_multi())

        if output == "scalar":
            return list(imgs)

        if output == "scalar+meta":
            return list(imgs), {i:asdict(m) for i, m in enumerate(metas)}

        tensor = _stack(imgs)

        if output == "nparray":
            return _to_numpy(tensor)

        if output == "nparray+meta":
            return _to_numpy(tensor), {i:asdict(m) for i, m in enumerate(metas)}

        if output == "tensor":
            return tensor

        if output == "tensor+meta":
            return tensor, {i:asdict(m) for i, m in enumerate(metas)}

        if output == "metatensor":
            return MetaTensor(
                x=tensor,
                meta = {i:asdict(m) for i, m in enumerate(metas)},
            )

        raise ValueError(f"Unknown output mode: {output}")

    # =====================================================
    # SINGLE CASE
    # =====================================================
    img, meta = _load(file_path)

    if output == "scalar":
        return img

    if output == "scalar+meta":
        return img, asdict(meta)

    tensor = img.data

    if squeeze:
        tensor = tensor.squeeze()

    tensor = tensor.to(dtype)

    if output == "nparray":
        return _to_numpy(tensor)

    if output == "nparray+meta":
        return _to_numpy(tensor), asdict(meta)

    if output == "tensor":
        return tensor

    if output == "tensor+meta":
        return tensor, asdict(meta)

    if output == "metatensor":
        return MetaTensor(x=tensor, meta=asdict(meta))

    raise ValueError(f"Unknown output mode: {output}")

